        "重点标注": "重要血管/神经走行变异识别"
      }
    ],
    "实践任务体系": [
      {
        "任务类型": "解剖图谱绘制",
        "要求": "手绘/数位板绘制包含肌群、血管、神经的复合结构图",
        "交付标准": "标注5处临床手术关键标志点",
        "周期": "每周2个器官系统"
      },
      {
        "任务类型": "病例逆向推导",
        "案例示例": "胰腺癌Whipple术式解剖要点",
        "任务目标": "根据术后并发症反推术中可能损伤的结构",
        "输出形式": "三维模型标注报告"
      }
    ],
    "临床衔接训练": [
      {
        "模块名称": "影像解剖挑战",
        "内容构成": [
          "CT/MRI断层图像与3D模型对照",
          "急诊创伤影像的解剖学解读",
          "肿瘤侵袭范围的立体定位分析"
        ],
        "训练频率": "每周3个临床案例"
      }
    ],
    "增强现实应用": {
      "推荐工具": "Microsoft HoloLens解剖套件",
      "核心训练": [
        "虚拟解剖台多层结构剥离",
        "手术入路动态模拟",
        "病理解剖对比观察"
      ],
      "达成标准": "完成10例AR临床场景演练"
    },
    "专家互动机制": {
      "安排项目": [
        "外科住院医师跟台观摩（重点观察解剖定位）",
        "病理科大体标本联合读片",
        "解剖学教授答疑工作坊"
      ],
      "预期成果": "建立临床解剖思维框架"
    },
    "能力评估体系": {
      "阶段考核": [
        "影像解剖空间测试（得分≥90%）",
        "手术视频关键结构识别挑战（30秒/结构）",
        "急诊虚拟仿真考核（包含出血控制演练）"
      ],
      "持续跟踪": "解剖临床应用能力成长曲线图谱"
    }
  }
}
```

Evaluation Dimension:
Instruction Following & Task Completion

Rubric:
5分： 完全理解并精准执行所有指令，完美达成核心任务目标，格式完全符合要求。
4分： 准确理解主要指令，正确执行任务，核心目标达成度高，格式基本符合要求，可能有极少细节遗漏或偏差。
3分： 理解了指令大意但可能忽略部分细节，任务基本完成但存在一些不准确或遗漏之处，格式有明显尝试但存在较多偏差。
2分： 对指令理解有偏差，任务完成度低或有严重错误，格式多数不符合要求。
1分： 完全误解或无视指令，任务未完成或完全错误，格式混乱或不相关。

